//! 📇️ Sparse source ordinals retain fixed radix pages and invalidate entries by generation.
use super::{PreparationIdentity,PreparationTurn};
use semio_framework_value::{RetireOwned,RetirementDemand,retained_clone::RetainedCloneProgress};
type Leaf=Box<[[u32;2];512]>;type Branch=Box<[Option<Leaf>;256]>;type Top=Box<[Option<Branch>;256]>;type Root=Box<[Option<Top>;256]>;
#[derive(RetireOwned)]
pub struct SourceVertexIndex{identity:PreparationIdentity,limit:usize,root:Option<Root>,bytes:usize,work:usize,closing:bool,closed:bool}
impl SourceVertexIndex{
 pub fn new(identity:PreparationIdentity,limit:usize)->Self{Self{identity,limit,root:None,bytes:0,work:0,closing:false,closed:false}}
 pub fn allocated_bytes(&self)->usize{self.bytes}pub fn work(&self)->usize{self.work}
 fn key(index:u32)->(usize,usize,usize,usize){let page=index as usize/512;((page>>16)&255,(page>>8)&255,page&255,index as usize%512)}
 fn enter(&mut self,turn:&mut PreparationTurn<'_,'_>,copy:usize,capacity:usize,release:usize)->Result<bool,&'static str>{turn.cx.original_source_parent().map_err(|_|"vertex-index-requires-original-source")?;if self.identity!=*turn.identity||turn.identity.operation!=turn.cx.operation().0||turn.identity.generation!=turn.cx.generation().0{return Err("vertex-index-original-caller-changed")}if turn.cx.is_cancelled()&&!self.closing{return Ok(false)}let demand=RetirementDemand{copy_bytes:copy,capacity_bytes:capacity,release_bytes:release,depth:4};if turn.cx.fuel_remaining()==0||(if self.closing{turn.cx.retirement_should_yield()}else{turn.cx.should_yield()})||!turn.cx.retained_work_can_enter(demand){return Ok(false)}turn.cx.consume_fuel(1);turn.cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:capacity,released_bytes:release}).map_err(|_|"vertex-index-original-receipt")?;self.work+=1;Ok(true)}
 fn allocation(&mut self,bytes:usize,turn:&mut PreparationTurn<'_,'_>,overhead:usize,remaining:usize)->Result<bool,&'static str>{if bytes>remaining||self.bytes.checked_add(bytes).is_none_or(|value|value>self.limit){return Err("vertex-index-byte-limit")}let copy=bytes.checked_mul(2).and_then(|v|v.checked_add(overhead)).ok_or("vertex-index-copy-demand")?;if !self.enter(turn,copy,bytes,0)?{return Ok(false)}self.bytes+=bytes;Ok(true)}
 pub fn get(&self,index:u32,generation:u32)->Result<u32,&'static str>{if generation==0{return Err("vertex-index-invalid-key")}if self.closing||self.closed{return Err("vertex-index-no-longer-owned")}let(a,b,c,d)=Self::key(index);Ok(self.root.as_ref().and_then(|root|root[a].as_ref()).and_then(|top|top[b].as_ref()).and_then(|branch|branch[c].as_ref()).and_then(|leaf|(leaf[d][1]==generation).then_some(leaf[d][0])).unwrap_or(0))}
 pub fn put(&mut self,index:u32,vertex:u32,generation:u32,turn:&mut PreparationTurn<'_,'_>,overhead:usize,remaining:usize)->Result<bool,&'static str>{if vertex==0||generation==0{return Err("vertex-index-invalid-value")}if self.closing||self.closed{return Err("vertex-index-no-longer-owned")}let(a,b,c,d)=Self::key(index);if self.root.is_none(){if self.allocation(std::mem::size_of::<[Option<Top>;256]>(),turn,overhead,remaining)?{self.root=Some(Box::new(std::array::from_fn(|_|None)));}return Ok(false)}if self.root.as_ref().unwrap()[a].is_none(){if self.allocation(std::mem::size_of::<[Option<Branch>;256]>(),turn,overhead,remaining)?{self.root.as_mut().unwrap()[a]=Some(Box::new(std::array::from_fn(|_|None)));}return Ok(false)}if self.root.as_ref().unwrap()[a].as_ref().unwrap()[b].is_none(){if self.allocation(std::mem::size_of::<[Option<Leaf>;256]>(),turn,overhead,remaining)?{self.root.as_mut().unwrap()[a].as_mut().unwrap()[b]=Some(Box::new(std::array::from_fn(|_|None)));}return Ok(false)}if self.root.as_ref().unwrap()[a].as_ref().unwrap()[b].as_ref().unwrap()[c].is_none(){if self.allocation(std::mem::size_of::<[[u32;2];512]>(),turn,overhead,remaining)?{self.root.as_mut().unwrap()[a].as_mut().unwrap()[b].as_mut().unwrap()[c]=Some(Box::new([[0;2];512]));}return Ok(false)}if !self.enter(turn,8usize.checked_add(overhead).ok_or("vertex-index-copy-demand")?,0,0)?{return Ok(false)}self.root.as_mut().unwrap()[a].as_mut().unwrap()[b].as_mut().unwrap()[c].as_mut().unwrap()[d]=[vertex,generation];Ok(true)}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn close(&mut self,turn:&mut PreparationTurn<'_,'_>)->Result<bool,&'static str>{if self.closed{return Ok(true)}if !self.closing{return Err("vertex-index-close-not-started")}let Some(root)=self.root.as_ref()else{if self.enter(turn,0,0,0)?{self.closed=true;}return Ok(self.closed)};let Some(a)=root.iter().rposition(Option::is_some)else{let bytes=std::mem::size_of::<[Option<Top>;256]>();if self.enter(turn,0,0,bytes)?{self.root=None;self.bytes-=bytes;}return Ok(false)};let top=root[a].as_ref().unwrap();let Some(b)=top.iter().rposition(Option::is_some)else{let bytes=std::mem::size_of::<[Option<Branch>;256]>();if self.enter(turn,0,0,bytes)?{self.root.as_mut().unwrap()[a]=None;self.bytes-=bytes;}return Ok(false)};let branch=top[b].as_ref().unwrap();let Some(c)=branch.iter().rposition(Option::is_some)else{let bytes=std::mem::size_of::<[Option<Leaf>;256]>();if self.enter(turn,0,0,bytes)?{self.root.as_mut().unwrap()[a].as_mut().unwrap()[b]=None;self.bytes-=bytes;}return Ok(false)};let bytes=std::mem::size_of::<[[u32;2];512]>();if self.enter(turn,0,0,bytes)?{self.root.as_mut().unwrap()[a].as_mut().unwrap()[b].as_mut().unwrap()[c]=None;self.bytes-=bytes;}Ok(false)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.root.is_none()&&self.bytes==0}
}
#[cfg(test)]#[path="🧪️tests/🦀️.rs"]mod tests;
